using System;using System.IO;using System.Text;using System.Diagnostics;using System.Drawing;using System.Collections.Generic;using System.Security.AccessControl;using System.Security.Principal;using System.Web.Script.Serialization;using System.Windows.Forms;
namespace StopSurvey {
 sealed class Window:Form {
  string cdb,exe,dir,log,stage="not_started",failure=null;Process proc;bool running=false,launched=false,identity=false;int? exit=null;
  Button bc=new Button(),bw=new Button(),start=new Button(),copy=new Button(),save=new Button();CheckBox login=new CheckBox(),interrupted=new CheckBox();Label state=new Label();Timer timer=new Timer();
  public Window(){Text="WoW CDB Stop Survey 0.1.0 — no API hooks";ClientSize=new Size(790,505);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;
   var intro=new Label{Left=15,Top=15,Width=755,Height=100,Text="LAB ONLY: launch the previously analysed game under CDB, without API breakpoints.\r\nNo game RIP edits, loader bypass or forced exception continuation. This can still prevent launch.\r\nNo login required; do not use a valuable account. Close all existing WoW processes first.\r\nAt an unexpected CDB prompt: Copy stop command, paste into CDB + Enter, then Save JSON."};
   bc.Text="Choose x64 cdb.exe";bc.SetBounds(15,120,220,34);bw.Text="Choose Wow.exe";bw.SetBounds(250,120,220,34);start.Text="Start lab game";start.SetBounds(485,120,270,34);
   copy.Text="Copy stop command";copy.SetBounds(15,170,220,34);save.Text="Save JSON";save.SetBounds(250,170,220,34);save.Enabled=false;
   login.Text="Game reached normal login screen (this run)";login.SetBounds(15,220,740,28);interrupted.Text="I used Ctrl+C BEFORE recording this stop";interrupted.SetBounds(15,252,740,28);state.SetBounds(15,295,740,195);
   Controls.AddRange(new Control[]{intro,bc,bw,start,copy,save,login,interrupted,state});
   string p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),@"Windows Kits\10\Debuggers\x64\cdb.exe");if(File.Exists(p))cdb=p;
   state.Text="The previous control passed on your machine. This tool does not rerun it.\r\nChoose the same official CDB and the previously analysed Wow.exe.\r\nNo installation or protection changes are performed.";
   bc.Click+=delegate{using(var d=new OpenFileDialog()){d.Filter="Microsoft CDB|cdb.exe";if(d.ShowDialog(this)==DialogResult.OK&&String.Equals(Path.GetFileName(d.FileName),"cdb.exe",StringComparison.OrdinalIgnoreCase))cdb=d.FileName;}};
   bw.Click+=delegate{using(var d=new OpenFileDialog()){d.Filter="Analysed game|Wow.exe";if(d.ShowDialog(this)==DialogResult.OK)exe=d.FileName;}};
   start.Click+=delegate{Launch();};copy.Click+=delegate{try{Clipboard.SetText(Core.Capture);state.Text="At a STOPPED CDB prompt, paste the copied command and press Enter.\r\nThen press Save JSON here. Do not continue an unknown exception.\r\nAfter saving: qd + Enter detaches. If CDB is still running, Ctrl+C first;\r\ncheck the Ctrl+C box if used BEFORE capture (it changes the event being observed).";}catch{state.Text="Clipboard failed. The exact command is also in README.fa.md.";}};
   save.Click+=delegate{Export("manual_snapshot");};timer.Interval=1200;timer.Tick+=delegate{Poll();};
   FormClosing+=delegate(object s,FormClosingEventArgs e){if(running)e.Cancel=MessageBox.Show(this,"CDB may still be attached. Closing this helper does NOT detach or stop it.\r\nAt a CDB prompt use qd + Enter, not q or the X button. Close helper anyway?","Debugger may be active",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes;};
  }
  string PrivateDir(){string p=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"WowCdbStopSurvey",Guid.NewGuid().ToString("N"));var a=new DirectorySecurity();a.SetAccessRuleProtection(true,false);var u=WindowsIdentity.GetCurrent().User;a.SetOwner(u);foreach(var id in new SecurityIdentifier[]{u,new SecurityIdentifier(WellKnownSidType.LocalSystemSid,null)})a.AddAccessRule(new FileSystemAccessRule(id,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(p,a);if(!new DirectoryInfo(p).GetAccessControl().AreAccessRulesProtected)throw new InvalidOperationException();return p;}
  void Launch(){if(running||launched)return;if(cdb==null||exe==null){state.Text="Choose cdb.exe and Wow.exe first.";return;}
   if(MessageBox.Show(this,"Launch the lab game UNDER CDB? Debugger/account compatibility is not guaranteed.\r\nThis tool sets NO API breakpoints and will NOT force continuation at a game exception.\r\nNo account login required. Raw local logs can contain private paths/debug strings.\r\nContinue?","Lab debugger consent",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;
   try{identity=false;failure=null;stage="identity_check";if(!String.Equals(Path.GetFileName(exe),"Wow.exe",StringComparison.OrdinalIgnoreCase)||Core.Sha(exe)!=Core.WowHash||Core.Sha(Path.Combine(Path.GetDirectoryName(exe),"wow_loader.dll"))!=Core.LoaderHash)throw new InvalidOperationException("identity");identity=true;
    var ps=Process.GetProcessesByName("Wow");bool any=ps.Length>0;foreach(var p in ps)p.Dispose();if(any){state.Text="Close all existing WoW processes normally, then retry.";return;}
    dir=PrivateDir();string boot=Path.Combine(dir,"boot.txt"),symbols=Path.Combine(dir,"local-symbols");Directory.CreateDirectory(symbols);File.WriteAllText(boot,Core.Boot,Encoding.ASCII);log=Path.Combine(dir,"debugger-local.log");
    var si=new ProcessStartInfo(cdb);si.UseShellExecute=false;si.CreateNoWindow=false;si.WorkingDirectory=Path.GetDirectoryName(exe);si.Arguments="-G -y "+Core.Quote(symbols)+" -logo "+Core.Quote(log)+" -cf "+Core.Quote(boot)+" "+Core.Quote(exe);
    si.EnvironmentVariables.Remove("SSLKEYLOGFILE");si.EnvironmentVariables.Remove("_NT_SYMBOL_PATH");si.EnvironmentVariables.Remove("_NT_ALT_SYMBOL_PATH");stage="starting_debugger";proc=Process.Start(si);if(proc==null)throw new InvalidOperationException();running=launched=true;stage="debugger_running";bc.Enabled=bw.Enabled=start.Enabled=false;save.Enabled=true;timer.Start();
    state.Text="If CDB stops unexpectedly: Copy stop command, paste in CDB + Enter, then Save JSON.\r\nDo not type g/gh/gN to force an unknown game exception.\r\nIf normal login opens, check its box; close game normally, then Save JSON.\r\nSend ONLY stop-survey-result-....json; never the raw debugger log.";
   }catch(Exception e){failure=e.GetType().Name;stage="preflight_or_launch_failed";Export("preflight_or_launch_failed");}
  }
  void Poll(){try{if(proc!=null&&proc.HasExited){running=false;exit=proc.ExitCode;stage="debugger_exited";timer.Stop();Export("debugger_exited");}}catch{timer.Stop();stage="monitor_failed";Export("monitor_failed");}}
  string Read(out bool tail,out bool read){tail=false;read=false;try{if(log==null)return "";using(var f=new FileStream(log,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){const int max=2*1024*1024;long len=f.Length;tail=len>max;if(tail)f.Seek(len-max,SeekOrigin.Begin);byte[] b=new byte[max];int n=0;while(n<b.Length){int k=f.Read(b,n,b.Length-n);if(k==0)break;n+=k;}string t=Encoding.Default.GetString(b,0,n);if(tail){int i=t.IndexOf('\n');t=i<0?"":t.Substring(i+1);}read=true;return t;}}catch{return "";}}
  void Export(string status){try{if(proc!=null){proc.Refresh();running=!proc.HasExited;if(!running){exit=proc.ExitCode;stage="debugger_exited";}}bool tail,read;string t=Read(out tail,out read);var d=new Dictionary<string,object>();d["schema"]="wow-cdb-stop-survey-1";d["version"]="0.1.0";d["status"]=status;d["last_stage"]=stage;d["failure_exception_kind"]=failure;d["game_launch_requested_via_cdb"]=launched;d["debugger_still_running"]=running;d["debugger_exit_code"]=exit;d["disk_wow_and_loader_hashes_matched"]=identity;d["loaded_memory_identity_attested"]=false;d["control_rerun_in_this_package"]=false;d["stop_observation"]=Core.Parse(t);d["user_reports_login_reached"]=login.Checked;d["user_reports_ctrl_c_before_capture"]=interrupted.Checked;d["log_read"]=read;d["log_tail_only"]=tail;d["syntax_error_observed_in_inspected_log"]=t.IndexOf("Syntax error",StringComparison.OrdinalIgnoreCase)>=0;d["api_breakpoints_added"]=false;d["game_context_or_code_explicitly_modified_by_tool"]=false;d["forced_game_exception_continuation_requested"]=false;d["payloads_keys_credentials_or_raw_logs_exported"]=false;d["firewall_hosts_certificates_execution_policy_changed"]=false;d["native_windows_integration_tested_by_developer"]=false;
    d["limits"]=new string[]{"A debugger changes timing and OS debug behaviour even without API hooks; this is not passive network capture.","Only module-category + relative instruction address and exception metadata enter JSON. Raw local logs may contain private data; do not upload them.","An observed loader RVA match does not prove anti-cheat, the exception handler path, crypto backend or telemetry.","The initial loader stop is continued by g in the boot script. No automatic continuation is sent for subsequent game stops.","If Ctrl+C was used before capture, the interrupt may replace the original event; do not attribute it to game failure.","Two MiB log tail only; no hard raw-log disk cap. No child process coverage, payload decoding or destination attribution.","The helper neither kills nor detaches automatically. qd detaches but is not a guarantee the game will recover."};
    string name="stop-survey-result-"+Guid.NewGuid().ToString("N")+".json";using(var f=new FileStream(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name),FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] b=new UTF8Encoding(false).GetBytes(new JavaScriptSerializer().Serialize(d));f.Write(b,0,b.Length);}save.Enabled=launched;state.Text="Saved: "+name+"\r\nSend ONLY this JSON. No raw log.\r\nIf stopped in CDB, qd + Enter detaches; do not force an unknown exception.\r\nIf you ticked login/Ctrl+C after this save, press Save JSON again and send the latest.";
   }catch{state.Text="Could not save JSON. Keep the tool folder writable. Do not upload raw logs.";}}
  protected override void Dispose(bool d){if(d){timer.Dispose();if(proc!=null)proc.Dispose();}base.Dispose(d);}
  [STAThread]static void Main(){Core.Tests();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Window());}
 }
